-- [nfnl] fnl/plugins/jira.fnl
return {"letieu/jira.nvim", opts = {jira = {base = "https://your-domain.atlassian.net", email = "your-email@example.com", token = "your-api-token", type = "basic", limit = 200}, active_sprint_query = "project = '%s' AND Sprint IN openSprints() ORDER BY Rank DESC", projects = {CP = {story_point_field = "customfield_10038", queries = {MyTasks = "project = '%s' AND assignee = currentUser() AND statusCategory != Done orderBy updated DESC", Backlog = "project = '%s' AND statusCategory != DONE orderBy Rank DESC", NextSprint = "project = '%s' AND Sprint IN futureSprints() ORDER BY Rank DESC"}}}}}
